import{_ as a,o as i,c as t,ag as s}from"./chunks/framework.hKI8yxB_.js";const u=JSON.parse('{"title":"从 2.x 迁移到 3.x","description":"","frontmatter":{},"headers":[],"relativePath":"migration.md","filePath":"migration.md"}'),o={name:"migration.md"};function l(d,e,n,r,p,c){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="从-2-x-迁移到-3-x" tabindex="-1">从 2.x 迁移到 3.x <a class="header-anchor" href="#从-2-x-迁移到-3-x" aria-label="Permalink to &quot;从 2.x 迁移到 3.x&quot;">​</a></h1><h2 id="vue-支持范围" tabindex="-1">Vue 支持范围 <a class="header-anchor" href="#vue-支持范围" aria-label="Permalink to &quot;Vue 支持范围&quot;">​</a></h2><p>3.x 支持 Vue 2.7.x 和 Vue 3.2.47+。Vue 3 的最低支持基线为 3.2.47，并使用当前工具链检查发布产物的类型兼容性。Vue 2 项目推荐升级到 2.7.16，2.6 及更早版本请继续使用组件库 2.x。</p><p>Vue 2.7 已自带 Composition API。项目中不再需要为了本组件库安装 <code>vue-demi</code> 或 <code>@vue/composition-api</code>，也不再执行 <code>vue-demi-switch</code>。其他依赖若仍使用这些包，请按实际依赖关系保留。</p><p>业务组件中的 <code>ref</code>、<code>reactive</code>、<code>watch</code>、生命周期等直接从 <code>vue</code> 导入。</p><h2 id="注册和样式" tabindex="-1">注册和样式 <a class="header-anchor" href="#注册和样式" aria-label="Permalink to &quot;注册和样式&quot;">​</a></h2><p>Vue 3 继续通过 <code>createApp(...).use(VueTianditu, config)</code> 注册；Vue 2.7 使用 <code>Vue.use(VueTianditu, config)</code> 和 <code>new Vue(...)</code> 挂载。</p><p>推荐样式入口为 <code>vue-tianditu/style.css</code>；旧的 <code>vue-tianditu/lib/style.css</code> 仍可使用。</p><p>注册插件只保存加载配置，首次挂载地图或显式调用 <code>useApiLoader</code> 时才加载脚本。需要在地图挂载前使用原生 <code>T</code> 时，请显式等待加载器。</p><h2 id="api-加载变化" tabindex="-1">API 加载变化 <a class="header-anchor" href="#api-加载变化" aria-label="Permalink to &quot;API 加载变化&quot;">​</a></h2><ul><li>脚本加载失败、超时会拒绝 Promise；直接调用加载器时请捕获错误。</li><li><code>TdtMap</code> 的 <code>error</code> 事件用于接收 API 加载和初始化错误。</li><li>主 API 加载后仍可追加扩展；同一脚本的并发请求合并，失败后可以重试。</li><li>可配置 <code>apiUrl</code>、<code>pluginUrls</code> 和 <code>timeout</code>；详见 <a href="/vue-tianditu/api-loader.html">API 加载器</a>。</li><li>热力图新组件使用随应用打包的渲染内核，不需要配置 <code>plugins: [&quot;HeatmapOverlay&quot;]</code>。</li></ul><p>同一页面的天地图 API 只有一个全局运行时。请在首次加载前统一 Key 和版本，不要通过创建第二张地图来切换全局 API 版本。</p><h2 id="双向绑定" tabindex="-1">双向绑定 <a class="header-anchor" href="#双向绑定" aria-label="Permalink to &quot;双向绑定&quot;">​</a></h2><p>Vue 2.7 与 Vue 3 的模板语法仍有差异。例如信息窗口的 <code>target</code>：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Vue 2.7 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tdt-infowindow</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :target.sync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Vue 3 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tdt-infowindow</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> v-model:target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>普通 props、事件和新覆盖物默认插槽在两版中的用法一致。鼠标工具和车辆轨迹通过组件 ref 暴露方法，Vue 2.7/3 使用相同的方法名。</p><h2 id="新增组件" tabindex="-1">新增组件 <a class="header-anchor" href="#新增组件" aria-label="Permalink to &quot;新增组件&quot;">​</a></h2><ul><li><a href="/vue-tianditu/overlay/heatmap.html">TdtHeatmap</a>：经纬度权重数据、半径、渐变、透明度和动态更新。</li><li><a href="/vue-tianditu/overlay/custom-overlay.html">TdtCustomOverlay</a>：自定义 DOM、Vue 组件、定位锚点和鼠标交互。</li></ul><h2 id="类型和开发工具" tabindex="-1">类型和开发工具 <a class="header-anchor" href="#类型和开发工具" aria-label="Permalink to &quot;类型和开发工具&quot;">​</a></h2><p>组件库发布 JavaScript、CSS 和类型声明。Vue 2.7、Vue 3 消费示例分别验证同一份打包产物。</p><p>Vue Language Tools 3.1 及以后不再支持 Vue 2。Vue 2.7 示例使用 <code>vue-tsc 3.0.11</code>、TypeScript 5.9.x 和 <code>vueCompilerOptions.target: 2.7</code>；Vue 3 示例使用新版类型工具。查看 <a href="https://github.com/vuejs/language-tools/wiki/Vue-2-Compat-Guides" target="_blank" rel="noreferrer">官方 Vue 2 工具兼容说明</a>。</p><p>开发和 CI 的 Node.js 基线提高到 22.22.1+ 或 24+。构建、启动和提交钩子不再安装或切换 Vue 版本。</p><h2 id="ssr-与静态文档" tabindex="-1">SSR 与静态文档 <a class="header-anchor" href="#ssr-与静态文档" aria-label="Permalink to &quot;SSR 与静态文档&quot;">​</a></h2><p>模块导入和插件注册不会访问浏览器 DOM。直接加载 SDK 需要浏览器环境；地图实例只在客户端挂载后创建。在 VitePress 中用 <code>ClientOnly</code> 包裹地图示例。</p>`,24)])])}const k=a(o,[["render",l]]);export{u as __pageData,k as default};
